import React, { useState } from "react";
import styled from "styled-components";
import { useNotice } from "../context/NoticeContext";
import FileViewer from "./FileViewer";
import { Eye, EyeOff, Download, X } from "lucide-react";

const DimBackground = styled.div`
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.4);
  z-index: 999;
`;

const PopupOverlay = styled.div`
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 90%;
  max-height: 90vh;
  background: white;
  z-index: 1000;
  padding: 24px;
  overflow-y: auto;
  border-radius: 12px;
`;

const PopupHeader = styled.div`
  display: flex;
  justify-content: flex-end;
`;

const CloseButton = styled.button`
  background: none;
  border: none;
  cursor: pointer;
`;

const SectionRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  gap: 8px;
`;

const ActionButtons = styled.div`
  display: flex;
  align-items: center;
  gap: 4px;
`;

const Label = styled.span`
  display: flex;
  align-items: center;
  gap: 6px;
`;


const Icon = styled.span`
  font-size: 1.5rem;
`;

const DatasetPopup = ({ genome, onClose }) => {
  const [visibleSection, setVisibleSection] = useState(null);

  const toggleSection = (key) => {
    setVisibleSection((prev) => (prev === key ? null : key));
  };

  return (
    <>
      <DimBackground onClick={onClose} />
      <PopupOverlay>
        <PopupHeader>
          <CloseButton onClick={onClose}>
            <X />
          </CloseButton>
        </PopupHeader>
        <h2
          style={{
            fontSize: "3rem",
            fontWeight: "bold",
            marginBottom: "1rem",
            textAlign: "center",
          }}
        >
          {genome.name} - {genome.genomeId}
        </h2>

        <div>
          <SectionRow>
            <span>contig.fasta</span>
            <CloseButton>
              <Download />
            </CloseButton>
          </SectionRow>

          <SectionRow>
            <span>AMR Genes</span>
            <ActionButtons>
              <CloseButton onClick={() => toggleSection("amr")}>
                <Icon>{visibleSection === "amr" ? "🧐" : "🔍"}</Icon>
              </CloseButton>
              <CloseButton>
                <Download />
              </CloseButton>
            </ActionButtons>
          </SectionRow>

          <SectionRow>
            <span>Virulences</span>
            <ActionButtons>
              <CloseButton onClick={() => toggleSection("virulence")}>
                <Icon>{visibleSection === "virulence" ? "🧐" : "🔍"}</Icon>
              </CloseButton>
              <CloseButton>
                <Download />
              </CloseButton>
            </ActionButtons>
          </SectionRow>

          <SectionRow>
            <span>Kháng sinh (CSV)</span>
            <ActionButtons>
              <CloseButton onClick={() => toggleSection("resistance")}>
                <Icon>{visibleSection === "resistance" ? "🧐" : "🔍"}</Icon>
              </CloseButton>
              <CloseButton>
                <Download />
              </CloseButton>
            </ActionButtons>
          </SectionRow>

          <div style={{ marginTop: "24px" }}>
            {visibleSection === "amr" && <FileViewer content={genome.amr} />}
            {visibleSection === "virulence" && (
              <FileViewer content={genome.virulence} />
            )}
            {visibleSection === "resistance" && (
              <FileViewer content={genome.resistance} />
            )}
          </div>
        </div>
      </PopupOverlay>
    </>
  );
};

export default DatasetPopup;
